+    fn check_active_before_commit_with_root_role(
         &self,
         progress: &mut dyn FnMut() -> Result<()>,
         mut readback: Option<&mut native_authenticated::PostWriteReadback<'_>>,
         arithmetic: Option<&pon_commitment::FullRootArithmetic>,
